## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

## Why This Is Asked
Maintains real-time median in O(log n) per op with duplicates, a common interview pattern.

## Key Concepts
- Median maintenance with two heaps
- Lazy deletion for erase
- Size-balance invariants and edge cases
- Handling empty state

## Code Example
```javascript
class MedianMultiset {
  constructor(){ this.lower = new MaxHeap(); this.upper = new MinHeap(); this.delayed = new Map(); this.size = 0; }
  _pruneLower(){ while(!this.lower.isEmpty() && (this.delayed.get(this.lower.peek())||0)>0){ const v=this.lower.pop(); this.delayed.set(v,(this.delayed.get(v)||0)-1); } }
  _pruneUpper(){ while(!this.upper.isEmpty() && (this.delayed.get(this.upper.peek())||0)>0){ const v=this.upper.pop(); this.delayed.set(v,(this.delayed.get(v)||0)-1); } }
  _balance(){ if(this.lower.size>this.upper.size+1) this.upper.push(this.lower.pop()); else if(this.upper.size>this.lower.size) this.lower.push(this.upper.pop()); }
  insert(v){ if(this.lower.isEmpty()||v<=this.lower.peek()) this.lower.push(v); else this.upper.push(v); this.size++; this._balance(); }
  erase(v){ if(this.size===0) return; this.delayed.set(v,(this.delayed.get(v)||0)+1); this.size--; if(v<=this.lower.peek()) this._pruneLower(); else this._pruneUpper(); this._balance(); }
  getMedian(){ if(this.size===0) return null; this._pruneLower(); this._pruneUpper(); if(this.size%2===1) return this.lower.peek(); return (this.lower.peek()+this.upper.peek())/2; }
}
```

